import{_ as r,o as n,c as i,a3 as t}from"./chunks/framework.z_KJ15Ep.js";const a="/bilder/unterricht-kataloge/kataloge-sportbefreiung.png",c=JSON.parse('{"title":"Sportbefreiungsgründe im Katalog pflegen","description":"","frontmatter":{"title":"Sportbefreiungsgründe im Katalog pflegen","source_pageid":367,"source_revision":4418},"headers":[],"relativePath":"schild3/unterricht-kataloge/sportbefreiungen-allgemeine-kataloge.md","filePath":"schild3/unterricht-kataloge/sportbefreiungen-allgemeine-kataloge.md"}'),l={name:"schild3/unterricht-kataloge/sportbefreiungen-allgemeine-kataloge.md"};function g(o,e,s,d,p,u){return n(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="sportbefreiungsgrunde-im-katalog-pflegen" tabindex="-1">Sportbefreiungsgründe im Katalog pflegen <a class="header-anchor" href="#sportbefreiungsgrunde-im-katalog-pflegen" aria-label="Permalink to &quot;Sportbefreiungsgründe im Katalog pflegen&quot;">​</a></h1><p>Ergänzen Sie bei Bedarf die vorhandenen Befreiungsgründe und passen Sie die Sortierung des Katalogs an.</p><p><a href="/bilder/unterricht-kataloge/kataloge-sportbefreiung.png"><img src="'+a+'" alt="Der Karteireiter zeigt den Katalog Sportbefreiung." loading="lazy"></a></p><p><em>Der Karteireiter zeigt den Katalog Sportbefreiung.</em></p><p>Der Katalog der Sportbefreiungen ist bereits mit vielen Befreiungsgründen voreingestellt:</p><p>Sollte dieser Katalog nicht alle Einträge beinhalten, die Sie für die Schülerinnen und Schüler an Ihrer Schule benötigen, so können Sie (wie in jedem anderen Katalog auch) durch Anklicken des Plus <strong>+</strong> weitere Einträge vornehmen. Denken Sie abschließend an den Klick auf das Häkchen zur Bestätigung.</p><p>Eine benutzerdefinierte Sortierreihenfolge kann durch Wechsel auf <em>Benutzerdefiniert</em> in der Schaltfläche <em>Sortierung</em> erfolgen. Verschieben Sie hierzu mit Hilfe der Pfeile am linken Rand Ihre Favoriten nach vorne.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Sportbefreiungen_(Allgemeine_Kataloge)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 4418.</p>',9)])])}const h=r(l,[["render",g]]);export{c as __pageData,h as default};
